import{_ as o,o as d,c as a,a2 as t}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"认识 UMM","description":"","frontmatter":{"title":"认识 UMM","order":3},"headers":[],"relativePath":"zh/learn/mod/umm.md","filePath":"zh/learn/mod/umm.md","lastUpdated":1786943111000}'),n={name:"zh/learn/mod/umm.md"};function l(r,e,i,s,c,M){return d(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="认识-unitymodmanager-umm" tabindex="-1">认识 UnityModManager（UMM） <a class="header-anchor" href="#认识-unitymodmanager-umm" aria-label="Permalink to &quot;认识 UnityModManager（UMM）&quot;">​</a></h1><p>在写第一个 Mod 之前，先搞懂 UMM 是如何把 Mod「塞进」游戏里的。</p><h2 id="umm-是什么" tabindex="-1">UMM 是什么 <a class="header-anchor" href="#umm-是什么" aria-label="Permalink to &quot;UMM 是什么&quot;">​</a></h2><p><strong>UnityModManager</strong> 是一个通用的 Unity 游戏 Mod 加载器。它通过运行时注入的方式，把 Mod 的 DLL 加载进游戏进程，并负责：</p><ul><li>发现 <code>Mods/</code> 目录下的所有 Mod</li><li>按 <code>Info.json</code> 识别每个 Mod 的身份</li><li>启用 / 禁用 Mod（对应 <code>OnToggle</code>）</li><li>提供一个设置面板（<code>Ctrl+F10</code>）</li><li>记录与输出 Mod 日志</li></ul><h2 id="mod-目录结构" tabindex="-1">Mod 目录结构 <a class="header-anchor" href="#mod-目录结构" aria-label="Permalink to &quot;Mod 目录结构&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ADOFAI/</span></span>
<span class="line"><span>├── Mods/</span></span>
<span class="line"><span>│   └── MyFirstMod/            # 每个 Mod 一个文件夹</span></span>
<span class="line"><span>│       ├── MyFirstMod.dll     # 编译产物</span></span>
<span class="line"><span>│       └── Info.json          # 清单文件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p>UMM 通过「Mod 文件夹名 / <code>Info.json</code> / DLL」三者的组合来识别一个 Mod。三者缺一不可。</p></blockquote><h2 id="umm-是如何加载-mod-的" tabindex="-1">UMM 是如何加载 Mod 的 <a class="header-anchor" href="#umm-是如何加载-mod-的" aria-label="Permalink to &quot;UMM 是如何加载 Mod 的&quot;">​</a></h2><ol><li>UMM 扫描 <code>Mods/</code> 下每个文件夹</li><li>读取 <code>Info.json</code>，找到 <code>EntryMethod</code>（例如 <code>MyFirstMod.Main.Load</code>）</li><li>通过反射调用 <code>Load(UnityModManager.ModEntry)</code> 静态方法</li><li><code>Load</code> 返回 <code>true</code> 表示加载成功；返回 <code>false</code> 则 UMM 判定该 Mod 加载失败</li><li>玩家启用 Mod 时，UMM 调用 <code>OnToggle(entry, true)</code></li></ol><h2 id="modentry-你与-umm-的接口" tabindex="-1">ModEntry：你与 UMM 的接口 <a class="header-anchor" href="#modentry-你与-umm-的接口" aria-label="Permalink to &quot;ModEntry：你与 UMM 的接口&quot;">​</a></h2><p><code>ModEntry</code> 是 UMM 交给你的「联络对象」，常用成员：</p><table tabindex="0"><thead><tr><th>成员</th><th>说明</th></tr></thead><tbody><tr><td><code>Info</code></td><td><code>Info.json</code> 解析结果（Id、Version、Author 等）</td></tr><tr><td><code>Logger.Log(msg)</code></td><td>输出日志到 UMM 界面</td></tr><tr><td><code>OnToggle</code></td><td>启停回调，Mod 的开关逻辑写在这里</td></tr><tr><td><code>OnGUI</code></td><td>设置面板绘制回调</td></tr><tr><td><code>OnSaveGUI</code></td><td>设置保存回调</td></tr><tr><td><code>Path</code></td><td>Mod 在磁盘上的目录（存配置、资源用）</td></tr><tr><td><code>Error(msg)</code></td><td>输出错误日志并标记 Mod 加载失败</td></tr></tbody></table><h2 id="日志去哪了" tabindex="-1">日志去哪了 <a class="header-anchor" href="#日志去哪了" aria-label="Permalink to &quot;日志去哪了&quot;">​</a></h2><ul><li>游戏内按 <code>Ctrl+F10</code> 打开 UMM 界面，右下角可以查看日志</li><li><code>Logger.Log</code> 与 <code>Debug.Log</code> 都会进入游戏日志文件</li><li>Windows 下游戏日志位于 <code>%APPDATA%\\..\\LocalLow\\7th Beat Games\\A Dance of Fire and Ice\\Player.log</code></li></ul><h2 id="你学到了什么" tabindex="-1">你学到了什么 <a class="header-anchor" href="#你学到了什么" aria-label="Permalink to &quot;你学到了什么&quot;">​</a></h2><ul><li>UMM 如何发现并加载 Mod</li><li>Mod 目录结构与 <code>Info.json</code> 的作用</li><li><code>ModEntry</code> 提供了哪些接口</li><li>在哪里看日志</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>用模板写一个能加载的最小 Mod → <a href="./first-mod">最小实例</a></p>`,19)])])}const p=o(n,[["render",l]]);export{h as __pageData,p as default};
